#include <stdlib.h>

int main() {
    int config_params[50];
    int param_value;
    int result;

    // Initialize config_params with test values
    for (int i = 0; i < 50; i++) {
        config_params[i] = i + 100; // Values from 100 to 149
    }

    printf("Testing for out-of-bounds read vulnerabilities...\n");

    // Test case 1: Negative index - potential out-of-bounds read
    printf("Testing negative index -1...\n");
    result = get_device_config_param(config_params, -1, &param_value);

    // Test case 2: Index at the boundary - just after the valid range
    printf("Testing index 50 (just after valid range)...\n");
    result = get_device_config_param(config_params, 50, &param_value);

    // Test case 3: Large positive index - potential out-of-bounds read
    printf("Testing large positive index 1000...\n");
    result = get_device_config_param(config_params, 1000, &param_value);

    // Test case 4: Index with maximum int value - potential out-of-bounds read
    printf("Testing maximum int value as index...\n");
    result = get_device_config_param(config_params, 2147483647, &param_value);

    // Test case 5: Index that could cause integer overflow when calculating offset
    printf("Testing potential overflow index...\n");
    result = get_device_config_param(config_params, 51, &param_value);

    printf("Security tests completed. If sanitizer errors occurred, they would be reported above.\n");
    return 0;
}

